INSERT OR IGNORE INTO stories (id, canonical_url, publisher, title, summary, published_at, topic, status) VALUES
('story-un-wsr-2026', 'https://www.un.org/sustainabledevelopment/blog/2026/10/world-social-report-2026-press-release/', 'UN Department of Economic and Social Affairs', 'World Social Report 2026', 'UN report on access to jobs, skills, services, infrastructure, and protections during economic, digital, and energy transitions.', '2026-10-15T00:00:00.000Z', 'TECH + SOCIETY', 'drafted'),
('story-ap-anthropic-2026', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', 'Associated Press', 'Anthropic expands AI support for nonprofits', 'Anthropic announced a Claude for Nonprofits plugin developed with nonprofits, expanded consultant support, and a proposed public benefit fund.', '2026-10-26T16:16:32.000Z', 'TECH + CIVIC LIFE', 'drafted');

INSERT OR IGNORE INTO questions (id, story_id, category, prompt, context, options_json, correct_index, explanation, source_title, source_url, source_published_at, status, suggested_by, reviewed_at, stale_at) VALUES
('wsr-2026-internet', 'story-un-wsr-2026', 'TECH + SOCIETY', 'The UN 2026 World Social Report says how many people lacked internet connectivity in 2025?', 'The report looks at how digital, economic, and energy transitions are changing who can take part in society.', '["About 2.2 billion","About 220 million","About 22 million","About 5.5 billion"]', 0, 'The report estimates that 2.2 billion people lacked internet connectivity in 2025. Access, affordability, and digital skills all shape who benefits from new technology.', 'UN World Social Report 2026', 'https://www.un.org/sustainabledevelopment/blog/2026/10/world-social-report-2026-press-release/', '2026-10-15T00:00:00.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('wsr-2026-informal-work', 'story-un-wsr-2026', 'WORK + SOCIETY', 'What share of workers worldwide were informally employed in 2025, according to the UN report?', 'Informal work often means work without the protections or benefits associated with formal employment.', '["18%","38%","58%","78%"]', 2, 'The report says 58% of workers worldwide were informally employed in 2025, a reminder that economic change affects people very differently.', 'UN World Social Report 2026', 'https://www.un.org/sustainabledevelopment/blog/2026/10/world-social-report-2026-press-release/', '2026-10-15T00:00:00.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('wsr-2026-young-women', 'story-un-wsr-2026', 'WORK + SOCIETY', 'The UN report estimates what share of young women aged 15 to 24 were not employed or in education or training in 2025?', 'The category is often shortened to NEET: not in employment, education, or training.', '["7%","17%","27%","47%"]', 2, 'The report estimates 27%. It uses the figure to illustrate how access to jobs, learning, and support remains uneven.', 'UN World Social Report 2026', 'https://www.un.org/sustainabledevelopment/blog/2026/10/world-social-report-2026-press-release/', '2026-10-15T00:00:00.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('anthropic-nonprofits-plugin', 'story-ap-anthropic-2026', 'TECH + CIVIC LIFE', 'Anthropic said its new Claude for Nonprofits plugin was developed with how many nonprofit organizations?', 'The company announced the plugin while also filing to sell shares to the public.', '["3","30","300","3,000"]', 1, 'The Associated Press reports that Anthropic created the plugin with 30 nonprofits to better fit their needs.', 'Associated Press', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', '2026-10-26T16:16:32.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('anthropic-consultants', 'story-ap-anthropic-2026', 'TECH + CIVIC LIFE', 'What new kind of help did Anthropic say it would make available to nonprofits with smaller, shorter-term projects?', 'The expansion is part of the company support program for nonprofit organizations.', '["Consultants","A new stock exchange","Free data centers","A grant-writing competition"]', 0, 'Anthropic said it would make consultants available to nonprofits for smaller, shorter-term projects, alongside its Claude for Nonprofits tools.', 'Associated Press', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', '2026-10-26T16:16:32.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('anthropic-nonprofit-users', 'story-ap-anthropic-2026', 'TECH + CIVIC LIFE', 'About how many nonprofits were already using Claude for Nonprofits, according to the AP report?', 'The story included examples of small organizations using the tool in their day-to-day work.', '["250","2,500","25,000","250,000"]', 2, 'The AP report said 25,000 nonprofits were using Claude for Nonprofits at the time of publication.', 'Associated Press', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', '2026-10-26T16:16:32.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('anthropic-public-benefit-fund', 'story-ap-anthropic-2026', 'TECH + CIVIC LIFE', 'Anthropic said it planned to commit what share of its stock to a proposed public benefit fund?', 'The fund could support nonprofits and people adversely affected by AI, but still needed shareholder approval after an IPO.', '["0.5%","5%","15%","50%"]', 1, 'The company announced plans to commit 5% of its shares to the proposed fund. The AP noted that shareholders would still need to approve it after the IPO.', 'Associated Press', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', '2026-10-26T16:16:32.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('anthropic-foodbank', 'story-ap-anthropic-2026', 'TECH + CIVIC LIFE', 'Which nonprofit did the AP story describe using Claude to improve food pickup and delivery scheduling?', 'The organization serves a county north of Houston, Texas.', '["Montgomery County Food Bank","The Ford Foundation","Allies Against Slavery","Taproot Foundation"]', 0, 'Montgomery County Food Bank said it used Claude to improve food pickup and delivery scheduling and to stay in touch with donors.', 'Associated Press', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', '2026-10-26T16:16:32.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('anthropic-pbc', 'story-ap-anthropic-2026', 'TECH + CIVIC LIFE', 'Anthropic describes itself as what kind of company, with a stated commitment to balance commercial interests and public good?', 'That corporate structure is one part of the company public explanation of its mission.', '["A public benefit corporation","A government agency","A charitable trust","A worker-owned cooperative"]', 0, 'Anthropic is a public benefit corporation. The AP story also notes that critics question how reliably this structure holds companies accountable to the public interest.', 'Associated Press', 'https://apnews.com/article/anthropic-claude-nonprofits-ai-e4db0d624495c8224187b3227939dd27', '2026-10-26T16:16:32.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z'),
('wsr-2026-inequality', 'story-un-wsr-2026', 'WORK + SOCIETY', 'Between 2000 and 2024, how many countries experienced rising income inequality, according to the UN report?', 'The report count includes countries at different income levels.', '["More than 10","More than 25","More than 50","More than 150"]', 2, 'More than 50 countries saw rising income inequality between 2000 and 2024, including 23 high-income countries.', 'UN World Social Report 2026', 'https://www.un.org/sustainabledevelopment/blog/2026/10/world-social-report-2026-press-release/', '2026-10-15T00:00:00.000Z', 'suggested', 'manual', NULL, '2026-11-13T00:00:00.000Z');
